const ROOT = process.cwd();
const DRY = process.argv.includes("--dry-run");
const UNDO = process.argv.includes("--undo");
const BAK = ".before-messages.bak";
const MARK = "Added by aura-messages-setup.cjs";
const SKIP_DIRS = new Set(["node_modules", "dist", "build", "out", "release", ".git", ".vite", "coverage"]);

const rel = (p) => path.relative(ROOT, p) || p;
const say = (line = "") => console.log(line);
function stop(lines) {
  say();
  say("Nothing was changed.");
  (Array.isArray(lines) ? lines : [lines]).forEach((l) => say("  " + l));
  say();
  process.exit(1);
}
function readText(file) {
  const raw = fs.readFileSync(file, "utf8");
  const eol = raw.includes("\r\n") ? "\r\n" : "\n"; // keep Windows line endings as they are
  return { text: raw.replace(/\r\n/g, "\n"), eol };
}
const withEol = (text, eol) => (eol === "\n" ? text : text.replace(/\n/g, eol));

function* walk(dir, depth = 0) {
  if (depth > 7) return;
  let entries = [];
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (!SKIP_DIRS.has(entry.name) && !entry.name.startsWith(".")) yield* walk(full, depth + 1);
    } else if (/\.(jsx?|tsx?|cjs|mjs)$/.test(entry.name) && !/^aura-[\w-]+\.cjs$/.test(entry.name)) {
      try { if (fs.statSync(full).size < 3 * 1024 * 1024) yield full; } catch {}
    }
  }
}
function findOne(label, test, hint) {
  const hits = [];
  for (const file of walk(ROOT)) {
    let text = "";
    try { text = fs.readFileSync(file, "utf8"); } catch { continue; }
    if (test(text)) hits.push(file);
  }
  if (hits.length === 1) return hits[0];
  if (!hits.length) stop(["I couldn't find " + label + ".", hint, "Copy this message to Claude."]);
  stop(["I found more than one file that looks like " + label + ":", ...hits.map((h) => "  " + rel(h)), "Copy this message to Claude."]);
}
const indentOf = (line) => line.match(/^\s*/)[0];
const findLine = (lines, re, from = 0, to = lines.length) => { for (let i = from; i < to; i++) if (re.test(lines[i])) return i; return -1; };

// ── supabase.js: share the signed-in connection with social.js ────────────────
function editSupabase(text) {
  const exp = /module\.exports\s*=\s*\{([^}]*)\}\s*;?/;
  const m = text.match(exp);
  if (!m || !/\bgetSession\b/.test(m[1])) throw new Error("the  module.exports = { ... }  line");
  if (/\binternals\s*:/.test(m[1])) return { text, notes: [] };
  if (!/^function client\s*\(/m.test(text) || !/^async function currentUser\s*\(/m.test(text)) throw new Error("the client() and currentUser() helpers");
  const names = m[1].trim().replace(/,\s*$/, "");
  const out = text.replace(exp, () =>
    "// social.js (friends and messages) uses the same signed-in connection through these two\n" +
    "module.exports = { " + names + ", internals: { client, currentUser } };");
  return { text: out, notes: ["shares its signed-in connection with social.js"] };
}

// ── Main file: one line ───────────────────────────────────────────────────────
function editMain(text) {
  if (/require\(\s*["']\.\/social["']\s*\)\.register\(/.test(text)) return { text, notes: [] };
  if (!/^const cloudHandler\s*=/m.test(text) || !/^const auraCloud\s*=\s*require\(/m.test(text)) throw new Error("the AURA accounts block ( const auraCloud = require(\"./supabase\") )");
  if (!/^let mainWin\b/m.test(text)) throw new Error("the line  let mainWin = null;");
  const lines = text.split("\n");
  // After the last account handler
  let at = -1;
  for (let i = 0; i < lines.length; i++) if (/^ipcMain\.handle\(\s*["'][\w:-]+["']\s*,\s*cloudHandler\(auraCloud\.\w+\)\s*\)\s*;?\s*$/.test(lines[i])) at = i;
  if (at < 0) throw new Error("the account handlers ( ipcMain.handle(\"profile:get\", cloudHandler(...)) )");
  lines.splice(at + 1, 0,
    "",
    "// AURA friends and messages. The work happens in social.js",
    'require("./social").register({ ipcMain, cloudHandler, cloud: auraCloud, getWindow: () => mainWin });');
  return { text: lines.join("\n"), notes: ["switches on social.js"] };
}

// ── preload.js: the bridge the window uses ────────────────────────────────────
const BRIDGE = `
// AURA friends and messages. Each call is answered by electron/social.js
contextBridge.exposeInMainWorld("auraSocial", {
  start: () => ipcRenderer.invoke("social:start"),
  stop: () => ipcRenderer.invoke("social:stop"),
  listFriends: () => ipcRenderer.invoke("social:listFriends"),
  findUser: (username) => ipcRenderer.invoke("social:findUser", username),
  requestFriend: (userId) => ipcRenderer.invoke("social:requestFriend", userId),
  acceptFriend: (friendshipId) => ipcRenderer.invoke("social:acceptFriend", friendshipId),
  removeFriend: (friendshipId) => ipcRenderer.invoke("social:removeFriend", friendshipId),
  getProfile: (userId) => ipcRenderer.invoke("social:getProfile", userId),
  listConversations: () => ipcRenderer.invoke("social:listConversations"),
  openConversation: (userId) => ipcRenderer.invoke("social:openConversation", userId),
  getMessages: (conversationId, before) => ipcRenderer.invoke("social:getMessages", conversationId, before),
  sendMessage: (conversationId, content) => ipcRenderer.invoke("social:sendMessage", conversationId, content),
  // Pictures, GIFs and videos: the file's bytes go to the main process, which uploads them
  sendMedia: (conversationId, file, caption) => ipcRenderer.invoke("social:sendMedia", conversationId, file, caption),
  mediaUrls: (paths) => ipcRenderer.invoke("social:mediaUrls", paths),
  // The background picture a chat shares between its two people (null removes it)
  setBackground: (conversationId, file) => ipcRenderer.invoke("social:setBackground", conversationId, file),
  markRead: (conversationId) => ipcRenderer.invoke("social:markRead", conversationId),
  // New messages and friend changes pushed from the main process
  onEvent: (cb) => {
    const h = (_e, data) => cb(data);
    ipcRenderer.on("social:event", h);
    return () => ipcRenderer.removeListener("social:event", h);
  },
});
`;
// Lines added to the bridge by later updates, each with the line it goes after
const BRIDGE_UPDATES = [
  { has: /\bsendMedia\s*:/, after: /^\s*sendMessage\s*:.*social:sendMessage.*,\s*$/, lines: [
    "  // Pictures, GIFs and videos: the file's bytes go to the main process, which uploads them",
    '  sendMedia: (conversationId, file, caption) => ipcRenderer.invoke("social:sendMedia", conversationId, file, caption),' ] },
  { has: /\bmediaUrls\s*:/, after: /^\s*sendMedia\s*:.*social:sendMedia.*,\s*$/, lines: [
    '  mediaUrls: (paths) => ipcRenderer.invoke("social:mediaUrls", paths),' ] },
  { has: /\bsetBackground\s*:/, after: /^\s*mediaUrls\s*:.*social:mediaUrls.*,\s*$/, lines: [
    "  // The background picture a chat shares between its two people (null removes it)",
    '  setBackground: (conversationId, file) => ipcRenderer.invoke("social:setBackground", conversationId, file),' ] },
];
function editPreload(text) {
  if (/exposeInMainWorld\(\s*["']auraSocial["']/.test(text)) {
    // The bridge from an earlier messages update is there: add whatever it doesn't have yet
    const lines = text.split("\n");
    const start = findLine(lines, /exposeInMainWorld\(\s*["']auraSocial["']/);
    let added = 0;
    for (const u of BRIDGE_UPDATES) {
      if (findLine(lines, u.has, start) >= 0) continue;
      const at = findLine(lines, u.after, start);
      if (at < 0) throw new Error("the place for a new line in the auraSocial bridge");
      lines.splice(at + 1, 0, ...u.lines);
      added++;
    }
    return added ? { text: lines.join("\n"), notes: ["added what's new to the window.auraSocial bridge"] } : { text, notes: [] };
  }
  if (!/\bcontextBridge\b/.test(text) || !/\bipcRenderer\b/.test(text)) throw new Error("contextBridge and ipcRenderer");
  return { text: text.replace(/\s*$/, "\n") + BRIDGE, notes: ["added the window.auraSocial bridge"] };
}

// ── App file ──────────────────────────────────────────────────────────────────
function editApp(text) {
  const lines = text.split("\n");
  const notes = [];
  const fail = (what) => { throw new Error(what); };

  // 1. Import
  if (!/from\s+["']\.\/components\/messages["']/.test(text)) {
    let at = findLine(lines, /^import\s.*from\s+["']\.\/cloudsync["']/);
    if (at < 0) at = findLine(lines, /^import\s.*from\s+["']\.\/components\/auth["']/);
    if (at < 0) fail("the import lines at the top (the one for ./cloudsync or ./components/auth)");
    lines.splice(at + 1, 0, 'import MessagesPage, { AuraFriendsTab, MessagesIcon, useAuraSocial } from "./components/messages";');
    notes.push("added the import");
  }

  const app = findLine(lines, /^function AuraApp\s*\(/);
  if (app < 0) fail("function AuraApp()");

  // 2. Start friends and messages, right after the toast function exists
  if (findLine(lines, /useAuraSocial\s*\(\s*\{/, app) < 0) {
    if (findLine(lines, /\[\s*view\s*,\s*setView\s*\]\s*=\s*useState/, app) < 0) fail("const [view,setView]=useState(...) inside AuraApp");
    let at = findLine(lines, /^\s*useCloudProfile\s*\(\s*\{/, app);
    if (at < 0) at = findLine(lines, /^\s*useCloudGames\s*\(/, app);
    if (at < 0) at = findLine(lines, /^\s*const toast\s*=\s*useCallback\(.*\}\s*,\s*\[[^\]]*\]\s*\)\s*;?\s*$/, app);
    if (at < 0) fail("the  const toast=useCallback(...)  line inside AuraApp");
    const nav = findLine(lines, /^\s*const navItems\s*=\s*\[\s*$/, app);
    if (nav >= 0 && nav < at) fail("the menu list (navItems) below the toast function, where I expected it");
    const pad = indentOf(lines[at]);
    lines.splice(at + 1, 0, pad + "// AURA friends and messages (see components/messages)", pad + "const social=useAuraSocial({view,toast,goTo:(id)=>goTo(id)});");
    notes.push("starts friends and messages inside AuraApp");
  }

  // 3. Messages in the left menu, under Social, with the unread count
  if (findLine(lines, /^\s*\{id:"messages",/, app) < 0) {
    const nav = findLine(lines, /^\s*const navItems\s*=\s*\[\s*$/, app);
    if (nav < 0) fail("the menu list ( const navItems = [ )");
    const end = findLine(lines, /^\s*\];\s*$/, nav);
    let at = findLine(lines, /^\s*\{id:"social",/, nav, end);
    if (at < 0) at = findLine(lines, /^\s*\{id:"streams",/, nav, end);
    if (at < 0) fail('the Social or Live Streams entry in the menu list');
    lines.splice(at + 1, 0, indentOf(lines[at]) + '{id:"messages",  icon:<MessagesIcon/>, label:"Messages",        badge:social.unread||null},');
    notes.push("Messages added to the left menu");
    // Controller navigation uses its own short list
    const pad = findLine(lines, /\{id:"social"\},\{id:"clips"\}/, app);
    if (pad >= 0 && !/\{id:"messages"\}/.test(lines[pad])) lines[pad] = lines[pad].replace('{id:"social"},{id:"clips"}', '{id:"social"},{id:"messages"},{id:"clips"}');
  }

  // 4. The Messages page fills the whole area, so the games search bar is hidden there
  const hdr = findLine(lines, /\{view!=="streams"(&&view!=="messages")?&&<header className="hdr">/, app);
  if (hdr < 0) fail('the page header line ( {view!=="streams"&&<header className="hdr"> )');
  if (!/view!=="messages"/.test(lines[hdr])) {
    lines[hdr] = lines[hdr].replace('{view!=="streams"&&<header className="hdr">', '{view!=="streams"&&view!=="messages"&&<header className="hdr">');
    notes.push("games search bar hidden on the Messages page");
  }

  // 5. The page itself
  if (findLine(lines, /\{view==="messages"&&<MessagesPage\b/, app) < 0) {
    const at = findLine(lines, /^\s*\{view==="settings"&&<Settings\b/, app);
    if (at < 0) fail('the Settings page line ( {view==="settings"&&<Settings ... )');
    if (findLine(lines, /\[\s*nowPlaying\s*,\s*setNowPlaying\s*\]\s*=\s*useState/, app) < 0) fail("const [nowPlaying, setNowPlaying] = useState(...) inside AuraApp");
    lines.splice(at, 0, indentOf(lines[at]) + '{view==="messages"&&<MessagesPage nowPlaying={nowPlaying}/>}', "");
    notes.push("Messages page added");
  }

  // 6. Notices. AURA only drew them on the Home page: on every other page the notice area was
  //    left empty, so "Friend request sent", errors and the rest never appeared there.
  const tcs = [];
  for (let i = app; i < lines.length; i++) if (/^\s*<div className="tc">\s*$/.test(lines[i])) tcs.push(i);
  const filled = tcs.find((i) => lines[i + 1] !== undefined && !/^\s*<\/div>\s*$/.test(lines[i + 1]));
  if (filled !== undefined) {
    let end = filled + 1;
    while (end < lines.length && !/^\s*<\/div>\s*$/.test(lines[end])) end++;
    const body = lines.slice(filled + 1, end);
    if (body.length && body.length <= 6 && body.every((l) => /^\s*\{(achToasts|toasts)\.map\(/.test(l))) {
      const from = indentOf(lines[filled]);
      for (const i of tcs.filter((n) => n !== filled).reverse()) {
        if (!/^\s*<\/div>\s*$/.test(lines[i + 1])) continue; // already has something in it
        const to = indentOf(lines[i]);
        lines.splice(i + 1, 0, ...body.map((l) => to + (l.startsWith(from) ? l.slice(from.length) : l.trimStart())));
        notes.push("notices now show on every page (they only appeared on Home before)");
      }
    }
  }

  // 7. "AURA" tab in the Friends panel
  const fp = findLine(lines, /^function FriendsPanel\s*\(/);
  if (fp < 0) fail("function FriendsPanel(");
  let fpEnd = findLine(lines, /^function \w+\s*\(/, fp + 1);
  if (fpEnd < 0) fpEnd = lines.length;
  if (findLine(lines, /<AuraFriendsTab\s*\/>/, fp, fpEnd) < 0) {
    const tabs = findLine(lines, /\[\s*"discord"\s*,\s*"steam"\s*(,\s*"xbox"\s*)?\]\.map\(/, fp, fpEnd);
    if (tabs < 0) fail('the Friends tabs line ( ["discord","steam"].map( )');
    const first = findLine(lines, /^\s*\{steamTab==="discord"&&\(\s*$/, fp, fpEnd);
    if (first < 0) fail('the line  {steamTab==="discord"&&(  in the Friends panel');
    lines[tabs] = lines[tabs].replace(/\[\s*"discord"\s*,/, '["aura","discord",');
    lines.splice(first, 0, indentOf(lines[first]) + '{steamTab==="aura"&&<AuraFriendsTab/>}', "");
    // Open on the AURA tab
    const st = findLine(lines, /\[\s*steamTab\s*,\s*setSteamTab\s*\]\s*=\s*useState\(\s*"discord"\s*\)/, fp, fpEnd);
    if (st >= 0) lines[st] = lines[st].replace(/useState\(\s*"discord"\s*\)/, 'useState("aura")');
    notes.push('"AURA" tab added to the Friends panel');
  }
  return { text: lines.join("\n"), notes };
}

// Does `node` accept the file? Catches a bad edit before anything is written.
function syntaxProblem(text) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "aura-check-"));
  const file = path.join(dir, "check.cjs");
  try {
    fs.writeFileSync(file, text);
    const r = spawnSync(process.execPath, ["--check", file], { encoding: "utf8" });
    return r.status === 0 ? "" : String(r.stderr || "syntax error").split("\n").filter(Boolean).slice(0, 4).join(" | ");
  } catch { return ""; } finally { try { fs.rmSync(dir, { recursive: true, force: true }); } catch {} }
}

// ── Undo ──────────────────────────────────────────────────────────────────────
function undo() {
  let restored = 0;
  const visit = (dir, depth = 0) => {
    if (depth > 7) return;
    let entries = [];
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        if (!SKIP_DIRS.has(entry.name) && !entry.name.startsWith(".")) visit(full, depth + 1);
      } else if (entry.name.endsWith(BAK)) {
        const target = full.slice(0, -BAK.length);
        fs.copyFileSync(full, target);
        fs.unlinkSync(full);
        say("  restored  " + rel(target));
        restored++;
      } else if (entry.name === "social.js" || entry.name === "messages.jsx") {
        try { if (fs.readFileSync(full, "utf8").includes(MARK)) { fs.unlinkSync(full); say("  removed   " + rel(full)); restored++; } } catch {}
      }
    }
  };
  say();
  visit(ROOT);
  say(restored ? "Undo finished. AURA is back to how it was before friends and messages." : "Nothing to undo.");
  say("The tables in Supabase are left alone.");
  say();
}

// ── Run ───────────────────────────────────────────────────────────────────────
function run() {
  if (!fs.existsSync(path.join(ROOT, "package.json"))) {
    stop(["This isn't your AURA project folder (no package.json here).", "Move this file next to package.json and run it from there."]);
  }
  if (UNDO) return undo();

  const need = "Run the earlier setup scripts first (accounts and sync), then run this again.";
  const files = {
    main: findOne("your main file", (t) => /^const auraCloud\s*=\s*require\(\s*["']\.\/supabase(?:\.js)?["']\s*\)/m.test(t) && /ipcMain\.handle\(/.test(t), need),
    supabase: findOne("supabase.js", (t) => /createClient/.test(t) && /async function getSession\s*\(/.test(t) && /module\.exports/.test(t), need),
    preload: findOne("preload.js", (t) => /exposeInMainWorld\(\s*["']auraCloud["']/.test(t), need),
    app: findOne("your App file", (t) => /function AuraApp\s*\(/.test(t) && /function FriendsPanel\s*\(/.test(t) && /AuthGate/.test(t), need),
  };
  const edits = { main: editMain, supabase: editSupabase, preload: editPreload, app: editApp };
  const labels = { main: "main file", supabase: "supabase", preload: "preload", app: "App file" };

  // Work everything out first, so nothing is written unless every edit fits
  const plan = [];
  const problems = [];
  for (const id of Object.keys(files)) {
    const { text, eol } = readText(files[id]);
    try {
      const result = edits[id](text);
      if (id !== "app" && result.text !== text) { const bad = syntaxProblem(result.text); if (bad) throw new Error("a way to edit it safely (" + bad + ")"); }
      plan.push({ id, file: files[id], before: text, after: result.text, eol, notes: result.notes });
    } catch (e) { problems.push("In " + rel(files[id]) + " I couldn't find " + e.message + "."); }
  }

  // The two new files
  const created = [
    { label: "social", file: path.join(path.dirname(files.main), "social.js"), content: FILES.social },
    { label: "messages", file: path.join(path.dirname(files.app), "components", "messages.jsx"), content: FILES.messages },
  ];
  for (const c of created) {
    c.note = "created";
    if (fs.existsSync(c.file)) {
      const existing = readText(c.file).text;
      if (!existing.includes(MARK)) problems.push(rel(c.file) + " already exists and wasn't made by this script, so I left it alone.");
      else c.note = existing === c.content ? "already done" : "updated";
    }
  }
  if (problems.length) stop([...problems, "Copy this message to Claude."]);

  say();
  say(DRY ? "Dry run. This is what would change:" : "AURA friends and messages");
  say();
  for (const step of plan) {
    if (step.after !== step.before && !DRY) {
      const bak = step.file + BAK;
      if (!fs.existsSync(bak)) fs.copyFileSync(step.file, bak);
      fs.writeFileSync(step.file, withEol(step.after, step.eol));
    }
    say("  " + (labels[step.id] + ":").padEnd(11) + rel(step.file));
    (step.notes.length ? step.notes : ["already done"]).forEach((n) => say("             - " + n));
  }
  for (const c of created) {
    if (c.note !== "already done" && !DRY) { fs.mkdirSync(path.dirname(c.file), { recursive: true }); fs.writeFileSync(c.file, c.content); }
    say("  " + (c.label + ":").padEnd(11) + rel(c.file));
    say("             - " + c.note);
  }
  say();
  if (DRY) { say("Run it again without --dry-run to apply."); say(); return; }
  say("Done. Two things left:");
  say("  1. Run aura-messages-background.sql in Supabase (SQL Editor), if you haven't yet.");
  say("     (New to messages? Run aura-messages.sql, then aura-messages-media.sql, then that one.)");
  say("  2. Fully restart AURA (stop it in the terminal, then start it again).");
  say("To undo later:  node aura-messages-setup.cjs --undo");
  say();
}

try { run(); } catch (e) { stop(["Something unexpected went wrong: " + e.message, "Copy this message to Claude."]); }
